package feature

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// v04Router mirrors the router generated by `forge init` since v0.4: no
// middleware stack, so there is no r.Use line to anchor on.
const v04Router = `package transport

import (
	"encoding/json"
	"net/http"

	"github.com/go-chi/chi/v5"
)

func NewRouter() http.Handler {
	r := chi.NewRouter()
	r.Get("/health", func(w http.ResponseWriter, _ *http.Request) {
		_ = json.NewEncoder(w).Encode("ok")
	})
	return r
}
`

func writeV04Router(t *testing.T) (string, string) {
	t.Helper()
	root := t.TempDir()
	path := filepath.Join(root, "internal", "transport", "http", "router.go")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(v04Router), 0o644); err != nil {
		t.Fatal(err)
	}
	return root, path
}

func TestIntegrateRouterGoV04MiddlewareBeforeRoutes(t *testing.T) {
	root, path := writeV04Router(t)

	err := IntegrateRouterGo(root, RouterIntegration{
		ImportPath:      "example.com/app/internal/cors",
		MiddlewareCall:  "r.Use(cors.Middleware())",
		MiddlewareCheck: "cors.Middleware()",
	})
	if err != nil {
		t.Fatalf("IntegrateRouterGo: %v", err)
	}

	data, _ := os.ReadFile(path)
	src := string(data)
	use := strings.Index(src, "r.Use(cors.Middleware())")
	route := strings.Index(src, "r.Get(")
	if use == -1 || use > route {
		t.Fatalf("middleware must be registered before routes (chi panics otherwise):\n%s", src)
	}
	if strings.Index(src, "chi.NewRouter()") > use {
		t.Fatalf("middleware must follow router creation:\n%s", src)
	}
}

func TestIntegrateRouterGoV04RouteRegistrationBeforeReturn(t *testing.T) {
	root, path := writeV04Router(t)

	err := IntegrateRouterGo(root, RouterIntegration{
		ImportPath:      "example.com/app/internal/swagger",
		MiddlewareCall:  "swagger.RegisterRoutes(r)",
		MiddlewareCheck: "swagger.RegisterRoutes",
	})
	if err != nil {
		t.Fatalf("IntegrateRouterGo: %v", err)
	}

	data, _ := os.ReadFile(path)
	src := string(data)
	if !strings.Contains(src, "\tswagger.RegisterRoutes(r)\n\treturn r") {
		t.Fatalf("route registration must be inserted before return r:\n%s", src)
	}

	if err := RemoveRouterGo(root, RouterIntegration{
		ImportPath:     "example.com/app/internal/swagger",
		MiddlewareCall: "swagger.RegisterRoutes(r)",
	}); err != nil {
		t.Fatalf("RemoveRouterGo: %v", err)
	}
	data, _ = os.ReadFile(path)
	if string(data) != v04Router {
		t.Fatalf("remove should restore the original router, got:\n%s", data)
	}
}

func TestIntegrateMainGoSkipsUnusedImport(t *testing.T) {
	root := t.TempDir()
	mainPath := filepath.Join(root, "cmd", "server", "main.go")
	if err := os.MkdirAll(filepath.Dir(mainPath), 0o755); err != nil {
		t.Fatal(err)
	}
	original := "package main\n\nimport (\n\t\"log/slog\"\n\t\"os\"\n)\n\nfunc main() {\n\t_ = slog.New(slog.NewTextHandler(os.Stdout, nil))\n}\n"
	if err := os.WriteFile(mainPath, []byte(original), 0o644); err != nil {
		t.Fatal(err)
	}

	// The replacement targets the legacy v0.3 JSON logger, absent here.
	err := IntegrateMainGo(root, MainIntegration{
		ImportPath: "example.com/app/internal/logging",
		Replacements: []MainReplacement{{
			OldStr: `slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))`,
			NewStr: `logging.DefaultLogger()`,
			Check:  "slog.New",
		}},
	})
	if err != nil {
		t.Fatalf("IntegrateMainGo: %v", err)
	}

	data, _ := os.ReadFile(mainPath)
	if string(data) != original {
		t.Fatalf("main.go must stay unchanged (an unused import breaks compilation), got:\n%s", data)
	}
}

func TestUpdateEnvironmentDoesNotDuplicateKeys(t *testing.T) {
	root := t.TempDir()
	envPath := filepath.Join(root, ".env.example")
	if err := os.WriteFile(envPath, []byte("HTTP_PORT=8080\nJWT_SECRET=existing\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	if err := UpdateEnvironment(root, []string{"JWT_SECRET=other", "CORS_ENABLED=false"}); err != nil {
		t.Fatal(err)
	}
	if err := UpdateEnvironment(root, []string{"CORS_ENABLED=false"}); err != nil {
		t.Fatal(err)
	}

	data, _ := os.ReadFile(envPath)
	want := "HTTP_PORT=8080\nJWT_SECRET=existing\nCORS_ENABLED=false\n"
	if string(data) != want {
		t.Fatalf("got %q, want %q", data, want)
	}
}
